import org.junit.jupiter.api.Test;

class BindingSetReplayNullPlaceholderTest {

	private static final ValueFactory VALUE_FACTORY = SimpleValueFactory.getInstance();

	@Test
	void queryAndArrayBindingSetsKeepNullPlaceholdersOutOfIteration() {
		QueryBindingSet queryBindings = queryBindingSetWithExpressionError();
		ArrayBindingSet arrayBindings = arrayBindingSetWithExpressionError();

		assertNullPlaceholderContract(queryBindings);
		assertNullPlaceholderContract(arrayBindings);
	}

	@Test
	void replayingNullPlaceholderRowsKeepsExpressionErrorUnbound() throws Exception {
		for (BindingSet source : List.of(queryBindingSetWithExpressionError(), arrayBindingSetWithExpressionError())) {
			try (BindingSetReplayBuffer buffer = new BindingSetReplayBuffer()) {
				assertDoesNotThrow(() -> buffer.append(source));
				buffer.seal();
				try (CloseableIteration<BindingSet> cursor = buffer.openCursor()) {
					BindingSet replayed = cursor.next();
					assertEquals("kept", replayed.getValue("kept").stringValue());
					assertNull(replayed.getValue("error"), "the expression-error target remains unbound after replay");
					assertFalse(cursor.hasNext());
				}
			}
		}
	}

	@Test
	void replayedUndefRowRemainsUnboundForStatementPatternComposition() throws Exception {
		BindingSet undef = new ListBindingSet(List.of("x"), (Value) null);
		BindingSet replayed;
		try (BindingSetReplayBuffer buffer = new BindingSetReplayBuffer()) {
			buffer.append(undef);
			buffer.seal();
			try (CloseableIteration<BindingSet> cursor = buffer.openCursor()) {
				replayed = cursor.next();
			}
		}

		BindingSetAssignment values = new BindingSetAssignment();
		values.setBindingNames(Set.of("x"));
		values.setBindingSets(List.of(replayed));
		IRI predicate = VALUE_FACTORY.createIRI("urn:test:p");
		Statement statement = VALUE_FACTORY.createStatement(VALUE_FACTORY.createIRI("urn:test:s"), predicate,
				VALUE_FACTORY.createIRI("urn:test:object"));
		StatementPattern pattern = new StatementPattern(Var.of("subject"), Var.of("predicate", predicate), Var.of("x"));
		QueryRoot root = new QueryRoot(new Join(values, pattern));
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(new SingleStatementSource(statement), null);

		List<BindingSet> rows;
		try (CloseableIteration<BindingSet> iteration = strategy.precompile(root)
				.evaluate(EmptyBindingSet.getInstance())) {
			rows = Iterations.asList(iteration);
		}

		assertEquals(1, rows.size(), "replaying parser UNDEF must not turn it into an expression-error marker");
		assertEquals(statement.getObject(), rows.get(0).getValue("x"));
	}

	private static void assertNullPlaceholderContract(BindingSet bindings) {
		assertTrue(bindings.getBindingNames().contains("error"),
				"the mutable evaluation binding set retains the placeholder name");
		assertTrue(bindings.hasBinding("error"), "the placeholder remains present to binding-name consumers");
		assertNull(bindings.getValue("error"), "the placeholder has no RDF value");
		assertEquals("kept", bindings.getValue("kept").stringValue());

		int visibleBindings = 0;
		for (Binding binding : bindings) {
			visibleBindings++;
			assertEquals("kept", binding.getName(), "null placeholders must not become iterator bindings");
		}
		assertEquals(1, visibleBindings);
	}

	private static QueryBindingSet queryBindingSetWithExpressionError() {
		QueryBindingSet bindings = new QueryBindingSet();
		bindings.setBinding("error", null);
		bindings.setBinding("kept", VALUE_FACTORY.createLiteral("kept"));
		return bindings;
	}

	private static ArrayBindingSet arrayBindingSetWithExpressionError() {
		ArrayBindingSet bindings = new ArrayBindingSet("error", "kept");
		bindings.getDirectSetBinding("error").accept(null, bindings);
		bindings.getDirectSetBinding("kept").accept(VALUE_FACTORY.createLiteral("kept"), bindings);
		return bindings;
	}

	private static final class SingleStatementSource implements TripleSource {
		private final Statement statement;

		private SingleStatementSource(Statement statement) {
			this.statement = statement;
		}

		@Override
		public CloseableIteration<? extends Statement> getStatements(Resource subject, IRI predicate,
				Value object, Resource... contexts)
				throws QueryEvaluationException {
			if ((subject == null || subject.equals(statement.getSubject()))
					&& (predicate == null || predicate.equals(statement.getPredicate()))
					&& (object == null || object.equals(statement.getObject()))) {
				return new CloseableIteratorIteration<>(List.of(statement).iterator());
			}
			return TripleSource.EMPTY_ITERATION;
		}

		@Override
		public ValueFactory getValueFactory() {
			return VALUE_FACTORY;
		}
	}
}
